fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    let n = a.len(); // Since a and b are guaranteed to be of equal length, we can use a.len()
    let mut result = Vec::with_capacity(n); // Create a new vector with the same capacity as the input vectors

    for i in 0..n {
        result.push(a[i] ^ b[i]); // Perform XOR and push the result into the new vector
    }

    result // Return the resulting vector
}